Contract ProcessSaleService::endSale(): Real {

            precondition:
          self.CurrentSale.oclIsUndefined() = false and self.CurrentSale.IsComplete = false and self.CurrentSale.IsReadytoPay = false

            postcondition:
          let total: Real = if self.CurrentSale.ContainedSalesLine@pre->isEmpty() then 0.0 else self.CurrentSale.ContainedSalesLine@pre->sumBy(line: SalesLineItem | line.Subamount@pre) endif in self.CurrentSale.Amount = total and self.CurrentSale.IsReadytoPay = true and result = total

        }
